contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function taking arbitrary callee and calldata
    function run(address callee, bytes memory data) public payable {
        require(true);

        // Record C's balance before the forwarding attempt
        uint256 balBefore = address(c).balance;

        // Attempt the forward and record whether it reverted
        bool reverted;
        c.forward(callee, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Record balance after
        uint256 balAfter = address(c).balance;

        // General rule:
        // If the call did not revert then C's balance is unchanged and the external call
        // to callee must have returned true (forward uses require(_s) so success implies _s==true).
        // We express this as: either reverted==true, or (balBefore==balAfter && reverted==false).
        // This asserts there is no successful execution that changes C's balance.
        assert(reverted || (balBefore == balAfter && !reverted));
    }

    receive() external payable {}
}

